import {VERSION,uid,mergeServices,esc} from './core.js';
import {parseNmap,validateScanEnvelope,compareScans} from './network.js';

export function createScanUI(ui){
  const {button,tag,showDialog,field,area,notify,download}=ui;const modes={tcp:'TCP ports',udp:'UDP ports',discovery:'Host discovery'};const modeField=value=>`<label class="field full">Acquisition mode<select name="mode">${Object.entries(modes).map(([k,v])=>`<option value="${k}" ${k===(value||'tcp')?'selected':''}>${v}</option>`).join('')}</select></label>`;
  let token='',status=null,message='',pollTimer=null,busy=false,preserving=false,comparisonEvidence=[];
  try{token=sessionStorage.getItem('probe-companion-token')||''}catch{}
  const local=()=>location.hostname==='127.0.0.1';
  const records=()=>ui.project()?.networkScans?.filter(x=>x.deviceId===ui.project().deviceId)||[];
  const api=async(path,method='GET',value)=>{
    try{token=sessionStorage.getItem('probe-companion-token')||''}catch{}
    if(!local())throw Error('Open PROBE from the companion URL printed in your terminal. Hosted PROBE imports scan evidence.');
    const response=await fetch('/api/'+path,{method,cache:'no-store',signal:AbortSignal.timeout(15000),headers:{'X-Probe-Client':'1',...(token?{Authorization:'Bearer '+token}:{}),...(method==='POST'?{'Content-Type':'application/json'}:{})},...(value!==undefined?{body:JSON.stringify(value)}:{})});
    let data;try{data=await response.json()}catch{throw Error('This address is not serving the PROBE companion. Start it and open its printed URL.');}
    if(!response.ok){if(response.status===401){token='';status=null;try{sessionStorage.removeItem('probe-companion-token')}catch{}}throw Error(data.error||'Companion request failed.');}return data;
  };
  function connectionBody(){
    if(!local())return `<p class="help-copy">Run native tools from the portable package on your assessment computer. The companion serves this same app and runs installed acquisition tools locally.</p><pre class="scan-command">node companion/server.mjs --allow 192.168.1.10</pre><p class="notice">Requires Node.js 22+. Scanning also needs Nmap; replace the example with your assessment scope. For debugging, add --debug-profiles ./my-debug-profiles.json and install OpenOCD plus ARM-capable GDB. Review the included DEBUGGER-BENCH.md before attaching. Extraction needs Linux bubblewrap and Python 3. Open the exact local URL printed in the terminal. The hosted app accepts XML and PROBE scan JSON imports. Linux is the initial validation platform; macOS remains unverified.</p>`;
    return `<p class="help-copy">Paste the pairing code printed by this companion. A new pairing replaces the previous browser token. Pairing lasts up to eight hours and is cleared when the companion restarts.</p><div class="form-grid">${field('Pairing code','code','','password',true)}</div>`;
  }
  function setup(){showDialog(local()?'Pair local companion':'Use the local companion',connectionBody(),local()?async data=>{const result=await api('pair','POST',{code:data.get('code').trim()});token=result.token;try{sessionStorage.setItem('probe-companion-token',token)}catch{}window.dispatchEvent(new Event('probe-paired'));await refresh();}:null,'Pair browser');}
  function panel(){
    const p=ui.project(),jobs=status?.jobs||[],active=jobs.find(j=>['running','stopping'].includes(j.status));
    const completed=jobs.filter(j=>!['running','stopping'].includes(j.status)&&j.projectId===p?.id&&j.deviceId===p?.deviceId&&!records().some(r=>r.jobId===j.id));
    return `<div class="panel-head"><h2>Native acquisition</h2>${tag(status?'PAIRED · LOCAL':'COMPANION')}</div><div class="panel-body"><div class="row between wrap"><div><strong>${status?(status.tool.available?'Nmap ready':'Nmap unavailable'):'Scan → preserve → repeat'}</strong><p class="muted smalltext spaced">${status?esc('Allowed targets: '+status.allowedScope.join(', ')):'Run scoped TCP/UDP scans and host discovery from the local companion. Existing imports work here.'}</p></div><div class="row wrap">${status?button('New scan','scan-new','primary','network',active?'disabled':'')+button('Refresh','scan-refresh','small',''):button(local()?'Pair companion':'Local setup','scan-setup','primary','network')}${button('Import scan JSON','scan-import','small','upload')}</div></div>${message?`<p class="notice spaced" role="status">${esc(message)}</p>`:''}${status&&!status.tool.available?`<p class="notice spaced">${esc(status.tool.error)}</p>`:''}${active?`<div class="baseline-row spaced"><div class="row between wrap"><strong>${esc(active.label)} · ${esc(active.status)}</strong>${button('Cancel scan','scan-cancel','small danger','',`data-id="${active.id}" ${active.status==='stopping'?'disabled':''}`)}</div><p class="smalltext spaced" role="status">${Math.max(0,Math.floor((Date.now()-Date.parse(active.startedAt))/1000))} seconds elapsed · ${active.xmlBytes.toLocaleString()} XML bytes · ${esc(active.progress||'Waiting for process to stop…')}</p><p class="muted smalltext">A scan continues if you close this page. Reopen and pair to recover its evidence.</p></div>`:''}${completed.length?`<div class="stack spaced"><h3>Completed jobs awaiting preservation</h3>${completed.map(j=>`<div class="row between wrap"><span><strong>${esc(j.label)}</strong> · ${esc(j.status)}</span><div class="row">${button('Preserve evidence','scan-save','small primary','',`data-id="${j.id}"`)}${button('Details','scan-job','small','',`data-id="${j.id}"`)}</div></div>`).join('')}</div>`:''}</div>`;
  }
  function history(){const rows=records();return `<section class="panel spaced"><div class="panel-head"><h2>Scan history & retest</h2><div class="row">${tag(rows.length+' SCANS')}${rows.length>1?button('Compare scans','scan-compare','small','clock'):''}</div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Scan / collected</th><th>Result</th><th>Scope</th><th>Actions</th></tr></thead><tbody>${rows.slice().reverse().map(r=>`<tr><td><strong>${esc(r.label)}</strong><span class="sub">${esc(new Date(r.startedAt).toLocaleString())}</span></td><td>${tag(r.status)}<span class="sub">${r.complete?'All requested observations accounted for':'Partial / incomplete coverage'} · ${r.observations.length} observations</span></td><td>${r.profile.targets.length} hosts · ${r.profile.ports.length} ${esc(modes[r.profile.mode||'tcp'])}<span class="sub">${esc(r.profile.vantage)}</span></td><td><div class="row wrap">${button('Review','scan-review','small','',`data-id="${r.id}"`)}${button('Repeat setup','scan-repeat','small','',`data-id="${r.id}"`)}${button('Evidence','evidence-detail','small','',`data-id="${r.evidenceId}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="panel-body"><p class="muted smalltext">Preserve a completed job or import its scan JSON to build a repeatable assessment. A missing observation never establishes closure.</p></div>'}</section>`;}
  function update(){const el=document.querySelector('#native-scan-panel');if(el){const focused=document.activeElement?.closest('[data-action]');const action=focused?.dataset.action,id=focused?.dataset.id;el.innerHTML=panel();if(action)for(const b of el.querySelectorAll('[data-action]'))if(b.dataset.action===action&&b.dataset.id===id)b.focus({preventScroll:true});}}
  async function refresh(){if(busy)return;busy=true;clearTimeout(pollTimer);try{status=await api('status');message='';}catch(e){status=null;message=e.message;}finally{busy=false;update();if(token)pollTimer=setTimeout(refresh,2000);}}
  async function newScan(previous){
    if(!status){setup();return;}if(!status.tool.available)throw Error(status.tool.error);
    const p=ui.project(),d=p.devices.find(d=>d.id===p.deviceId),old=previous?.profile;
    showDialog(previous?'Repeat scan setup':'Configure native scan',`<div class="form-grid">${field('Scan label','label',previous?previous.label+' · retest':d.name+' · TCP scan','text',true)}${field('IPv4 / CIDRs or IPv6 (link-local requires %interface)','targets',old?.targets.join(', ')||'','text',true)}${modeField(old?.mode)}${field('Ports (TCP ≤256; UDP/discovery ≤16)','ports',old?.ports.join(',')||'22,80,443')}${field('Connect-scan rate ceiling (probes/s)','rate',old?.rate||20,'number')}${field('Overall timeout (seconds)','timeout',old?.timeout||120,'number')}${area('Vantage point & device state','vantage',old?.vantage||p.scope||'')}<label class="field full"><span><input type="checkbox" name="serviceDetection" ${old?.serviceDetection?'checked':''}> Enable service/version probes</span></label></div><p class="notice spaced">TCP uses connect scans. UDP requires --udp enabled and separately configured Nmap privileges; it is capped at 16 hosts × 16 ports. Discovery uses TCP probes to the selected ports. Link-local IPv6 requires the exact interface in both targets and the host allowlist. No DNS lookup or IPv6 CIDR expansion. Service detection sends additional application probes; the connect-scan rate setting does not bound all service probes. Allowlist: ${esc(status.allowedScope.join(', '))}. Review the exact destinations before starting.</p>`,async data=>{
      const input={mode:data.get('mode'),projectId:p.id,deviceId:p.deviceId,label:data.get('label'),targets:data.get('targets'),ports:data.get('ports'),rate:Number(data.get('rate')),timeout:Number(data.get('timeout')),vantage:data.get('vantage'),serviceDetection:data.has('serviceDetection')};
      const preview=await api('preview','POST',input);
      // showDialog closes after its async handler; open the next step on the following task.
      setTimeout(()=>showDialog('Review scan destinations',`<p><strong>${esc(input.label)}</strong> · ${preview.profile.targets.length} hosts × ${preview.profile.ports.length} ${esc(modes[input.mode])}</p><p class="scope-text spaced">${esc(preview.profile.targets.join(', '))}</p><p class="smalltext spaced">Ports: ${esc(preview.profile.ports.join(', '))}</p><p class="smalltext spaced">Vantage: ${esc(input.vantage)}</p><pre class="scan-command spaced">nmap ${esc(preview.args.join(' '))}</pre><p class="notice spaced">Starting this job sends network probes to the listed targets. Its profile, tool version and original output will be recorded locally.</p>`,async()=>{if(ui.project()?.id!==p.id||ui.project()?.deviceId!==p.deviceId)throw Error('Project/device changed. Start setup again.');await api('jobs','POST',input);await refresh();notify('Scan started. Preserve its evidence when it finishes.');},'Start scan'),0);
    },'Review destinations');
  }
  async function preserve(envelope){
    if(preserving)throw Error('Evidence preservation is already in progress.');preserving=true;
    try{return await preserveOnce(envelope)}finally{preserving=false}
  }
  async function preserveOnce(envelope){
    const p=ui.project(),deviceId=p.deviceId,bytes=await validateScanEnvelope(envelope),j=envelope.job;
    if((p.networkScans?.length||0)>=100)throw Error('This project retains up to 100 scan records. Export it and begin another assessment.');
    if(records().some(r=>r.jobId===j.id))throw Error('This job is already preserved for the selected device.');
    let parsed={observations:[],complete:false},parseError='';try{parsed=parseNmap(new TextDecoder().decode(bytes.xml),j.profile);}catch(e){parseError=e.message;}
    const serialized=JSON.stringify(envelope,null,2);
    const required=bytes.xml.length+new TextEncoder().encode(serialized).length;
    if(p.evidence.reduce((a,e)=>a+(e.size||0),0)+required>128*1024*1024)throw Error('Preserving both originals would exceed the project evidence limit. Export this project and start another.');
    const xml=await ui.evidenceFromFile(new File([bytes.xml],j.id+'.xml',{type:'application/xml'}),'Network scan','Original stdout, including incomplete output.',deviceId);
    const record=await ui.evidenceFromFile(new File([serialized],j.id+'.probe-scan.json',{type:'application/json'}),'Scan acquisition','Record plus exact XML/stderr bytes and their hashes.',deviceId);
    for(const e of [xml,record])Object.assign(e,{source:'PROBE local companion record (imported hashes checked)',tool:j.tool,conditions:j.profile.vantage+' · '+j.status+' · '+j.startedAt});
    const scan={id:uid('scan'),deviceId,jobId:j.id,label:j.label,profile:j.profile,status:j.status,startedAt:j.startedAt,endedAt:j.endedAt,complete:j.status==='completed'&&parsed.complete,observations:parsed.observations,hostObservations:parsed.hostObservations||[],parseError,evidenceId:record.id,xmlEvidenceId:xml.id};
    if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Active project or device changed; import again into the intended device.');
    p.evidence.push(xml,record);p.networkScans??=[];p.networkScans.push(scan);p.services=mergeServices(p.services,parsed.observations,deviceId,xml.id);ui.changed('Scan originals and metadata preserved. '+(scan.complete?'All requested observations accounted for.':'Coverage is incomplete; inspect the record.'));update();return scan;
  }
  async function getRecord(r){const e=ui.project().evidence.find(e=>e.id===r.evidenceId);if(!e)throw Error('Scan evidence is missing.');return JSON.parse(ui.rawText(e));}
  function details(e,r){const j=e.job;showDialog('Scan record',`<p><strong>${esc(j.label)}</strong> · ${esc(j.status)}</p><p class="muted smalltext spaced">${esc(j.tool)}<br>${esc(j.platform||'Platform not recorded')}<br>${esc(j.startedAt)} → ${esc(j.endedAt||'Running')}</p><pre class="scan-command spaced">nmap ${esc(j.args?.join(' ')||'Arguments unavailable')}</pre><p class="scope-text spaced">${esc(j.profile.vantage)}</p><p class="notice spaced">${esc(j.error||r?.parseError||'No process error recorded. Review scan coverage and collection conditions before interpreting results.')}</p>${r?.hostObservations?.length?`<h3 class="spaced">Host observations</h3><div class="table-wrap"><table><tbody>${r.hostObservations.map(h=>`<tr><td>${esc(h.host)}</td><td>${esc(h.state)}</td><td>${esc(h.reason)}</td></tr>`).join('')}</tbody></table></div><p class="notice">No response is not proof a device is absent. UDP open|filtered does not establish an open service.</p>`:''}<details class="spaced"><summary>Original stderr</summary><pre class="scan-command">${esc(new TextDecoder().decode(Uint8Array.from(atob(e.stderrBase64||''),c=>c.charCodeAt(0))))}</pre></details><div class="row wrap spaced">${button('Download scan JSON','scan-download','small','download',`data-id="${r?.id||j.id}"`)}${r?button('Original XML','evidence-download','small','download',`data-id="${r.xmlEvidenceId}"`):''}</div>`);}
  function compare(){const rows=records();showDialog('Compare scan observations',`<div class="form-grid"><label class="field">Before<select name="before">${rows.map(r=>`<option value="${r.id}">${esc(r.label)}</option>`).join('')}</select></label><label class="field">After<select name="after">${rows.map((r,i)=>`<option value="${r.id}" ${i===rows.length-1?'selected':''}>${esc(r.label)}</option>`).join('')}</select></label></div>`,async data=>{const a=rows.find(r=>r.id===data.get('before')),b=rows.find(r=>r.id===data.get('after'));if(a===b)throw Error('Choose two different scans.');const result=compareScans(a,b);comparisonEvidence=[a.evidenceId,b.evidenceId];setTimeout(()=>showDialog('Scan comparison',`<p><strong>${esc(a.label)}</strong> → <strong>${esc(b.label)}</strong></p><p class="notice spaced">${result.sameScope?'Host/port scope and detection mode match.':'Scopes or detection modes differ; this is not a like-for-like comparison.'} ${result.complete?'Both records account for their requested observations.':'At least one scan has incomplete coverage.'} Compare vantage point, firmware and device state before concluding remediation.</p><div class="table-wrap spaced"><table><thead><tr><th>Endpoint</th><th>Observed change</th></tr></thead><tbody>${result.changes.map(c=>`<tr><td>${esc(c.endpoint)}</td><td>${esc(c.detail)}</td></tr>`).join('')||'<tr><td colspan="2">No changed explicit observations.</td></tr>'}</tbody></table></div><div class="row spaced">${button('Create evidence-linked finding','scan-finding','small','plus')}</div>`),0);},'Compare');}
  const saved=()=>ui.project()?.scanProfiles?.filter(x=>x.deviceId===ui.project().deviceId)||[];
  function savedView(){return `<section class="panel spaced"><div class="panel-head"><h2>Saved scan profiles</h2>${button('New profile','scan-profile-new','small')}</div><div class="panel-body stack">${saved().map(x=>`<div class="row between wrap"><div><strong>${esc(x.name)}</strong><p class="muted smalltext">${esc(x.input.targets)} · ${esc(modes[x.input.mode||'tcp'])} ${esc(x.input.ports)}</p></div><div class="row">${button('Review & run','scan-profile-use','small','',`data-id="${x.id}"`)}${button('Edit','scan-profile-edit','small','',`data-id="${x.id}"`)}${button('Delete','scan-profile-delete','small','',`data-id="${x.id}"`)}</div></div>`).join('')||'<p class="muted">Reusable drafts. Every run is checked against the current companion allowlist and reviewed before starting.</p>'}</div></section>`;}
  function editProfile(id){const p=ui.project(),deviceId=p.deviceId,x=saved().find(x=>x.id===id),v=x?.input||{};showDialog('Saved scan profile',`<div class="form-grid">${field('Profile name','name',x?.name||'','text',true)}${field('Targets','targets',v.targets||'','text',true)}${modeField(v.mode)}${field('Ports','ports',v.ports||'22,80,443')}${field('Rate ceiling','rate',v.rate||20,'number')}${field('Timeout seconds','timeout',v.timeout||120,'number')}${area('Vantage and device state','vantage',v.vantage||'')}<label class="field"><span><input name="serviceDetection" type="checkbox" ${v.serviceDetection?'checked':''}> Service probes</span></label></div>`,async data=>{if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Device changed.');const record={id:x?.id||uid('profile'),deviceId,name:data.get('name').trim(),input:{mode:data.get('mode'),targets:data.get('targets').trim(),ports:data.get('ports').trim(),rate:Number(data.get('rate')),timeout:Number(data.get('timeout')),vantage:data.get('vantage'),serviceDetection:data.has('serviceDetection')}};const {validateSavedProfiles}=await import('./ip.js');const next=[...(p.scanProfiles||[]).filter(v=>v.id!==record.id),record];validateSavedProfiles({...p,scanProfiles:next});p.scanProfiles=next;ui.changed('Profile saved. Targets are validated again before every run.');},'Save profile');}
  async function action(name,id){if(!name.startsWith('scan-'))return false;
    if(name==='scan-profile-new')editProfile();
    else if(name==='scan-profile-edit')editProfile(id);
    else if(name==='scan-profile-delete'){ui.project().scanProfiles=ui.project().scanProfiles.filter(x=>x.id!==id);ui.changed('Saved profile deleted. Acquisitions retained.');}
    else if(name==='scan-profile-use'){const x=saved().find(x=>x.id===id);await newScan({label:x.name,profile:{...x.input,targets:x.input.targets.split(/[\s,]+/).filter(Boolean),ports:x.input.ports.split(',')}});}
    else if(name==='scan-setup')setup();
    else if(name==='scan-refresh')await refresh();
    else if(name==='scan-new')await newScan();
    else if(name==='scan-repeat'){const r=records().find(r=>r.id===id);if(r)await newScan(r);}
    else if(name==='scan-cancel'){await api('jobs/'+id+'/cancel','POST',{});await refresh();}
    else if(name==='scan-save'){await preserve(await api('jobs/'+id));}
    else if(name==='scan-job'){details(await api('jobs/'+id));}
    else if(name==='scan-review'){const r=records().find(r=>r.id===id);details(await getRecord(r),r);}
    else if(name==='scan-download'){const r=records().find(r=>r.id===id),e=r?await getRecord(r):await api('jobs/'+id);download(e.job.id+'.probe-scan.json',JSON.stringify(e,null,2));}
    else if(name==='scan-import')ui.pick('.json',async file=>{if(file.size>6*1024*1024)throw Error('Use a scan record under 6 MiB.');await preserve(JSON.parse(await file.text()));});
    else if(name==='scan-compare')compare();
    else if(name==='scan-finding')ui.findingDialog('',comparisonEvidence);
    return true;
  }
  function init(){if(local()&&token)refresh();}
  return {view:()=>`<section class="panel spaced" id="native-scan-panel">${panel()}</section>${savedView()}${history()}`,action,init};
}
